<?php
namespace Tests\Feature;
use App\Models\{User,Programme,Employer,TutorGroup,Apprentice,ApprenticeIntakeBatch as Batch};
use App\Support\{ApprenticeIntakes as I,StaffDuties};
use Illuminate\Foundation\Testing\LazilyRefreshDatabase;
use Illuminate\Support\Facades\{DB,Crypt,Notification};
use Illuminate\Support\Str;
use Illuminate\Http\UploadedFile;
use Illuminate\Validation\ValidationException;
use Tests\Support\AuditFault;
use Tests\TestCase;
class ApprenticeIntakeTest extends TestCase {
 use LazilyRefreshDatabase;
 private function fixture():array {$m=User::factory()->create(['role'=>'admin']);$n=User::factory()->create(['role'=>'ceo']);$t=User::factory()->create(['role'=>'tutor']);$p=Programme::factory()->create(['standard_code'=>'ST-INTAKE-'.Str::random(6),'version'=>'1.0']);$e=Employer::factory()->create();$g=TutorGroup::factory()->create(['programme_id'=>$p->id,'tutor_id'=>$t->id]);$v=array_fill_keys(I::HEADERS,'');$v=array_merge($v,['reference'=>'NEW-INTAKE-1','first_name'=>'Fictional','last_name'=>'Intake','email'=>'new-learner@example.test','programme_code'=>$p->standard_code,'programme_version'=>$p->version,'employer_reference'=>$e->reference,'group_reference'=>$g->reference,'tutor_email'=>$t->email,'start_date'=>'2027-01-11','planned_end_date'=>'2030-01-11']);return compact('m','n','t','p','e','g','v');}
 private function csv(array $rows):string {$f=fopen('php://temp','r+');fputcsv($f,I::HEADERS,',','"','');foreach($rows as$row){fputcsv($f,array_map(fn($key)=>$row[$key]??'',I::HEADERS),',','"','');}rewind($f);$s=stream_get_contents($f);fclose($f);return $s;}
 private function prepare(array $f,?array $rows=null,?string $request=null):Batch {return I::prepare($f['m'],1,$request??(string)Str::uuid(),$this->csv($rows??[$f['v']]),'Fictional Intake','PRIVATE-SOURCE-REFERENCE');}
 private function apply(array $f,Batch $b):void {I::decide($f['n'],1,$b,$b->version,'apply','PRIVATE-INDEPENDENT-CHECK');}
 private function invalid(callable $f):void {try{$f();$this->fail('Invalid intake accepted');}catch(ValidationException){$this->assertTrue(true);}}
 public function test_strict_template_round_trip_bom_crlf_quotes_and_normalisation():void {$f=$this->fixture();$v=$f['v'];$v['reference']='lower-ref';$v['email']='UPPER@example.test';$v['first_name']='Fictional, "Name"';$rows=I::parse("\xEF\xBB\xBF".str_replace("\n","\r\n",$this->csv([$v])));$this->assertSame('LOWER-REF',$rows[0]['reference']);$this->assertSame('upper@example.test',$rows[0]['email']);$this->assertSame($v['first_name'],$rows[0]['first_name']);}
 public function test_malformed_headers_quoting_binary_encoding_and_blank_lines_refuse():void {$f=$this->fixture();$csv=$this->csv([$f['v']]);foreach(['',"wrong\n",$csv."\n",str_replace('Fictional','bad"quote',$csv),$csv."\0",str_replace('Fictional',"\xff",$csv),str_repeat('x',500001)]as$s){$this->invalid(fn()=>I::parse($s));}}
 public function test_row_limit_and_field_count_are_enforced():void {$f=$this->fixture();$csv=$this->csv(array_fill(0,201,$f['v']));$this->invalid(fn()=>I::parse($csv));$this->invalid(fn()=>I::parse(implode(',',I::HEADERS)."\nonly,two\n"));}
 public function test_prepare_retains_encrypted_validated_source_without_profiles_accounts_tasks_or_messages():void {$f=$this->fixture();Notification::fake();$users=User::count();$b=$this->prepare($f);$this->assertTrue(I::fresh($b));$this->assertSame('Pending',$b->state);$this->assertDatabaseCount('apprentices',0);$this->assertSame($users,User::count());$this->assertDatabaseCount('learning_tasks',0);$raw=DB::table('apprentice_intake_batches')->value('source');$this->assertStringNotContainsString('PRIVATE-SOURCE',$raw);$this->assertStringContainsString('new-learner',Crypt::decryptString($raw));Notification::assertNothingSent();}
 public function test_apply_creates_all_profiles_with_canonical_assignments_and_no_active_programme_claim():void {$f=$this->fixture();$v=$f['v'];$v['reference']='NEW-2';$v['email']='second@example.test';$b=$this->prepare($f,[$f['v'],$v]);$users=User::count();$this->apply($f,$b);$b->refresh();$this->assertTrue(I::applied($b));$this->assertDatabaseCount('apprentices',2);$this->assertDatabaseCount('assignment_change_events',2);$this->assertDatabaseCount('programme_outcomes',0);$this->assertSame($users,User::count());$this->assertDatabaseCount('learning_tasks',0);$a=Apprentice::where('reference',$f['v']['reference'])->firstOrFail();$this->assertSame($f['t']->id,$a->tutor_id);$this->assertSame($f['p']->id,$a->programme_id);$this->assertNull($a->user_id);$this->assertSame('Applied',$b->state);}
 public function test_creator_cannot_apply_or_reject_but_can_withdraw():void {$f=$this->fixture();$b=$this->prepare($f);foreach(['apply','reject']as$d){$this->invalid(fn()=>I::decide($f['m'],1,$b,1,$d,'Self'));}I::decide($f['m'],1,$b,1,'withdraw','Withdraw');$this->assertSame('Withdrawn',$b->fresh()->state);$this->assertDatabaseCount('apprentices',0);}
 public function test_request_replay_is_idempotent_even_after_application_and_changed_payload_refuses():void {$f=$this->fixture();$request=(string)Str::uuid();$a=$this->prepare($f,null,$request);$this->assertSame($a->id,$this->prepare($f,null,$request)->id);$this->apply($f,$a);$this->assertSame($a->id,$this->prepare($f,null,$request)->id);$v=$f['v'];$v['reference']='OTHER';$this->invalid(fn()=>$this->prepare($f,[$v],$request));$this->assertDatabaseCount('apprentice_intake_batches',1);$this->assertDatabaseCount('apprentices',1);}
 public function test_existing_reference_never_updates_existing_profile_and_case_is_checked():void {$f=$this->fixture();$a=Apprentice::factory()->create(['reference'=>'new-intake-1','first_name'=>'ORIGINAL']);$b=$this->prepare($f);$this->assertFalse(I::fresh($b));$this->assertStringContainsString('Reference already exists',implode(' ',$b->source['rows'][0]['errors']));$this->invalid(fn()=>$this->apply($f,$b));$this->assertSame('ORIGINAL',$a->fresh()->first_name);}
 public function test_duplicate_file_reference_and_individual_email_block_whole_batch():void {$f=$this->fixture();$v=$f['v'];$v['reference']='NEW-2';foreach([[$f['v'],$f['v']],[$f['v'],$v]]as$rows){$b=$this->prepare($f,$rows);$this->assertFalse(I::fresh($b));$this->invalid(fn()=>$this->apply($f,$b));}$this->assertDatabaseCount('apprentices',0);}
 public function test_existing_learner_email_is_a_visible_identity_error():void {$f=$this->fixture();Apprentice::factory()->create(['email'=>$f['v']['email']]);$b=$this->prepare($f);$this->assertFalse(I::fresh($b));$this->assertStringContainsString('Email already used',implode(' ',$b->source['rows'][0]['errors']));}
 public function test_invalid_dates_missing_names_and_reference_errors_all_remain_visible():void {$f=$this->fixture();$v=$f['v'];$v['reference']='!bad';$v['first_name']='';$v['start_date']='2027-02-30';$v['planned_end_date']='2026-01-01';$b=$this->prepare($f,[$v]);$this->assertGreaterThanOrEqual(3,count($b->source['rows'][0]['errors']));$this->assertFalse(I::fresh($b));}
 public function test_unknown_or_inactive_programme_does_not_create_catalogue_or_profile():void {$f=$this->fixture();$f['p']->active=false;$f['p']->save();$b=$this->prepare($f);$this->assertFalse(I::fresh($b));$this->assertDatabaseCount('apprentices',0);$this->assertSame(1,Programme::where('standard_code',$f['p']->standard_code)->count());}
 public function test_wrong_group_programme_or_inactive_employer_blocks():void {$f=$this->fixture();$f['g']->programme_id=Programme::factory()->create()->id;$f['g']->save();$f['e']->active=false;$f['e']->save();$b=$this->prepare($f);$this->assertGreaterThanOrEqual(2,count($b->source['rows'][0]['errors']));$this->assertFalse(I::fresh($b));}
 public function test_wrong_or_inactive_tutor_and_wrong_subject_duty_block():void {$f=$this->fixture();$f['t']->active=false;$f['t']->save();$u=User::factory()->create(['role'=>'functional_skills_tutor','subject_scope'=>'english']);$v=$f['v'];$v['maths_email']=$u->email;$b=$this->prepare($f,[$v]);$this->assertGreaterThanOrEqual(2,count($b->source['rows'][0]['errors']));$this->assertFalse(I::fresh($b));}
 public function test_additional_careers_and_subject_duties_resolve_without_role_conversion():void {$f=$this->fixture();$u=User::factory()->create(['role'=>'staff']);StaffDuties::save($u,$f['m'],1,1,0,['careers_adviser'=>true,'maths_tutor'=>true]);$v=$f['v'];$v['careers_email']=$u->email;$v['maths_email']=$u->email;$b=$this->prepare($f,[$v]);$this->assertTrue(I::fresh($b));$this->apply($f,$b);$a=Apprentice::firstOrFail();$this->assertSame($u->id,$a->careers_adviser_id);$this->assertSame($u->id,$a->maths_tutor_id);$this->assertSame('staff',$u->fresh()->role);}
 public function test_optional_blanks_remain_warnings_and_no_automatic_exemptions_or_accounts():void {$f=$this->fixture();$v=$f['v'];$v['email']='';$v['employer_reference']='';$v['group_reference']='';$b=$this->prepare($f,[$v]);$this->assertTrue(I::fresh($b));$this->assertGreaterThan(4,count($b->source['rows'][0]['warnings']));$this->apply($f,$b);$a=Apprentice::firstOrFail();$this->assertNull($a->email);$this->assertNull($a->employer_id);$this->assertNull($a->user_id);}
 public function test_programme_group_employer_or_staff_change_stales_entire_batch():void {foreach(['p','g','e','t']as$key){$f=$this->fixture();$v=$f['v'];$v['reference']='UNIQUE-'.$key;$v['email']=$key.'@example.test';$b=$this->prepare($f,[$v]);$obj=$f[$key];$obj->record_version++;$obj->save();$this->assertFalse(I::fresh($b));$this->invalid(fn()=>$this->apply($f,$b));}$this->assertDatabaseCount('apprentices',0);}
 public function test_reference_claimed_after_preview_blocks_all_rows():void {$f=$this->fixture();$v=$f['v'];$v['reference']='SECOND';$v['email']='second@example.test';$b=$this->prepare($f,[$f['v'],$v]);Apprentice::factory()->create(['reference'=>'SECOND']);$this->assertFalse(I::fresh($b));$this->invalid(fn()=>$this->apply($f,$b));$this->assertDatabaseMissing('apprentices',['reference'=>$f['v']['reference']]);}
 public function test_two_previews_cannot_both_create_same_apprentice():void {$f=$this->fixture();$a=$this->prepare($f);$b=$this->prepare($f);$this->apply($f,$a);$this->invalid(fn()=>$this->apply($f,$b));$this->assertDatabaseCount('apprentices',1);}
 public function test_expired_and_creator_auth_changed_previews_hold():void {$f=$this->fixture();$b=$this->prepare($f);$this->travel(25)->hours();$this->assertFalse(I::fresh($b));$this->invalid(fn()=>$this->apply($f,$b));$this->travelBack();$f['m']->auth_version=2;$f['m']->save();$this->assertFalse(I::fresh($b));}
 public function test_required_audit_failure_rolls_back_profiles_and_assignment_history():void {$f=$this->fixture();$b=$this->prepare($f);AuditFault::install('intake_create_fault','audit_events','Synthetic fail','intake_profile_created');try{$this->apply($f,$b);$this->fail('Audit ignored');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('apprentices',0);$this->assertDatabaseCount('assignment_change_events',0);$this->assertSame('Pending',$b->fresh()->state);}
 public function test_final_event_failure_rolls_back_whole_creation():void {$f=$this->fixture();$b=$this->prepare($f);AuditFault::install('intake_event_fault','apprentice_intake_events','Synthetic fail','preview_apply');try{$this->apply($f,$b);$this->fail('Audit ignored');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('apprentices',0);$this->assertSame('Pending',$b->fresh()->state);}
 public function test_preview_event_failure_leaves_no_batch():void {$f=$this->fixture();AuditFault::install('intake_preview_fault','apprentice_intake_events','Synthetic fail');try{$this->prepare($f);$this->fail('Audit ignored');}catch(\Illuminate\Database\QueryException){}$this->assertDatabaseCount('apprentice_intake_batches',0);}
 public function test_forged_state_or_altered_expiry_cannot_look_applied():void {$f=$this->fixture();$b=$this->prepare($f);DB::table('apprentice_intake_batches')->where('id',$b->id)->update(['state'=>'Applied']);$this->assertFalse(I::applied($b->fresh()));$this->assertSame([],I::cohort($b->fresh()));DB::table('apprentice_intake_batches')->where('id',$b->id)->update(['expires_at'=>now()->addDays(9)]);$this->assertFalse(I::intact($b->fresh()));$this->actingAs($f['m'])->get('/apprentice-intakes/'.$b->id)->assertStatus(409);}
 public function test_manager_and_actor_versions_are_checked():void {$f=$this->fixture();$b=$this->prepare($f);$f['n']->auth_version=2;$f['n']->save();try{$this->apply($f,$b);$this->fail('Stale actor');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame(403,$e->getStatusCode());}$f['n']->active=false;$f['n']->save();try{I::decide($f['n'],2,$b,1,'apply','Inactive');$this->fail('Inactive actor');}catch(\Symfony\Component\HttpKernel\Exception\HttpException $e){$this->assertSame(403,$e->getStatusCode());}}
 public function test_live_cohort_flags_show_account_tasks_and_owner_gaps_then_follow_current_profile():void {$f=$this->fixture();$b=$this->prepare($f);$this->apply($f,$b);$b->refresh();$cohort=I::cohort($b);$this->assertCount(1,$cohort);$this->assertTrue($cohort[0]['current']);$this->assertContains('Login not linked',$cohort[0]['issues']);$this->assertSame(0,$cohort[0]['tasks']);$this->actingAs($f['m'])->get('/apprentice-intakes/'.$b->id)->assertOk()->assertSee('Live setup for this intake')->assertSee('Link account / invitation setup');}
 public function test_changed_created_identity_is_not_silently_matched_to_a_different_person():void {$f=$this->fixture();$b=$this->prepare($f);$this->apply($f,$b);$b->refresh();$a=Apprentice::firstOrFail();$a->reference='CHANGED';$a->save();$row=I::cohort($b)[0];$this->assertFalse($row['current']);$this->assertArrayNotHasKey('name',$row);}
 public function test_non_managers_cannot_view_prepare_or_export():void {$f=$this->fixture();$b=$this->prepare($f);foreach(['tutor','mentor','staff','apprentice','employer','careers_adviser','inclusion_lead']as$role){$u=User::factory()->create(['role'=>$role]);$this->actingAs($u);foreach(['/apprentice-intakes','/apprentice-intakes/new','/apprentice-intakes/catalogue','/apprentice-intakes/template.csv','/apprentice-intakes/'.$b->id,'/apprentice-intakes/'.$b->id.'/setup.json']as$url){$this->get($url)->assertForbidden();}$this->post('/apprentice-intakes',[])->assertForbidden();$this->post('/apprentice-intakes/'.$b->id,[])->assertForbidden();}}
 public function test_upload_validation_requires_csv_request_source_and_confirmation():void {$f=$this->fixture();$this->actingAs($f['m']);$data=['file'=>UploadedFile::fake()->createWithContent('intake.csv',$this->csv([$f['v']])),'request_token'=>(string)Str::uuid(),'title'=>'Fictional','reference'=>'Fictional source','confirmed'=>1];foreach(['file','reference','confirmed','request_token']as$key){$d=$data;unset($d[$key]);$this->post('/apprentice-intakes',$d)->assertSessionHasErrors($key);}$this->post('/apprentice-intakes',$data)->assertRedirect()->assertSessionHasNoErrors();$this->assertDatabaseCount('apprentice_intake_batches',1);}
 public function test_template_catalogue_filters_headers_and_privacy():void {$f=$this->fixture();$this->actingAs($f['m'])->get('/apprentice-intakes/template.csv')->assertOk()->assertSee(implode(',',I::HEADERS),false)->assertHeader('Referrer-Policy','no-referrer');$this->get('/apprentice-intakes/catalogue?kind=staff')->assertOk()->assertSee($f['t']->email)->assertDontSee($f['m']->password);$this->get('/apprentice-intakes/catalogue?search=%25')->assertOk()->assertDontSee($f['p']->name);$this->get('/apprentice-intakes/catalogue?kind=bad')->assertSessionHasErrors('kind');}
 public function test_minimal_report_omits_source_personal_names_emails_and_notes():void {$f=$this->fixture();$b=$this->prepare($f);$this->apply($f,$b);$this->actingAs($f['m'])->get('/apprentice-intakes/'.$b->id.'/setup.json')->assertOk()->assertJsonPath('applied_proof_verified',true)->assertDontSee('PRIVATE-')->assertDontSee('new-learner@example.test')->assertDontSee('Fictional Intake')->assertDontSee('bindings')->assertJsonPath('private_source_names_emails_and_notes_exported',false);}
 public function test_withdraw_and_reject_error_previews_do_not_create_records():void {$f=$this->fixture();$v=$f['v'];$v['reference']='!bad';$a=$this->prepare($f,[$v]);I::decide($f['n'],1,$a,1,'reject','Invalid');$b=$this->prepare($f,[$v]);I::decide($f['m'],1,$b,1,'withdraw','Correct file');$this->assertSame('Rejected',$a->fresh()->state);$this->assertSame('Withdrawn',$b->fresh()->state);$this->assertDatabaseCount('apprentices',0);}
 public function test_stale_decision_and_replay_cannot_create_twice():void {$f=$this->fixture();$b=$this->prepare($f);$this->invalid(fn()=>I::decide($f['n'],1,$b,2,'apply','Stale'));$this->apply($f,$b);$this->invalid(fn()=>$this->apply($f,$b));$this->assertDatabaseCount('apprentices',1);}
 public function test_existing_user_mailbox_is_never_auto_linked_or_role_converted():void {$f=$this->fixture();$u=User::factory()->create(['role'=>'tutor','email'=>$f['v']['email']]);$b=$this->prepare($f);$this->apply($f,$b);$this->assertNull(Apprentice::firstOrFail()->user_id);$this->assertSame('tutor',$u->fresh()->role);}
 public function test_get_requests_are_read_only_and_decisions_are_post_only():void {$f=$this->fixture();$b=$this->prepare($f);$this->actingAs($f['m']);foreach(['/apprentice-intakes','/apprentice-intakes/new','/apprentice-intakes/catalogue','/apprentice-intakes/'.$b->id]as$url){$this->get($url)->assertOk();}$this->assertDatabaseCount('apprentices',0);$this->assertDatabaseCount('apprentice_intake_events',1);}
}
